{"database":"research_db","query":"UPDATE measurements
SET notes = 'Cognitive score normalized from pilot 0-50 to 0-100.'
WHERE session_id IN (SELECT session_id FROM pilot_sessions)
  AND notes LIKE 'Normalized from pilot 0-50 to 0-100;%';
SELECT m.session_id, m.participant_id, m.condition, m.cognitive_score, m.reaction_ms, m.notes
FROM measurements m JOIN pilot_sessions p ON p.session_id = m.session_id
ORDER BY m.session_id;
SELECT r.analysis_id, r.metric, r.condition, r.value, r.n,
       CASE WHEN r.metric = 'mean_cognitive_score' THEN (SELECT ROUND(AVG(cognitive_score),1) FROM measurements WHERE condition = r.condition AND status='valid')
            WHEN r.metric = 'mean_reaction_ms' THEN (SELECT ROUND(AVG(reaction_ms),1) FROM measurements WHERE condition = r.condition AND status='valid') END AS recomputed_value,
       (SELECT COUNT(*) FROM measurements WHERE condition = r.condition AND status='valid') AS recomputed_n
FROM results_summary r ORDER BY r.analysis_id;
SELECT COUNT(*) AS unintegrated_pilot_rows FROM pilot_sessions p WHERE NOT EXISTS (SELECT 1 FROM measurements m WHERE m.session_id = p.session_id);
SELECT entry_id, author, date, message FROM changelog WHERE entry_id = 'CL-3';"}
